-- FAQ de Teclab, tanda 4b (28/11/2026): Diseño de Producto Digital (249), Gestión de IA y
-- Transformación Digital (250), Administración de Negocios Digitales Financieros (252) y Gestión de
-- Proyectos Mineros (244) de 5 a 9. Textos aprobados por el usuario. Fuentes: fichas oficiales de
-- teclab.edu.ar y plan en D1. Ninguna articula con Siglo 21 según carreras/teclab/articulaciones-teclab.json.
-- Cada UPDATE exige el JSON y el título actuales: si alguno cambió, no escribe.
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión de Proyectos Mineros?","respuesta":"Estudiás la industria minera, sus operaciones y su legislación, junto con gestión de proyectos, presupuestos, logística, proveedores y análisis de datos operativos. La formación suma tecnologías digitales aplicadas a la gestión minera."},{"pregunta":"¿Qué hace un técnico en Gestión de Proyectos Mineros?","respuesta":"Organiza cronogramas, hitos y reportes de avance, procesa datos técnicos, operativos y administrativos, asiste en compras, contratos y seguimiento de proveedores, y utiliza indicadores y herramientas digitales de gestión."},{"pregunta":"¿Cuál es la salida laboral de Gestión de Proyectos Mineros?","respuesta":"Empresas operadoras, en seguimiento de proyectos y control de gestión; proveedores y contratistas, en organización de servicios y documentación administrativa; consultoras especializadas, y áreas de compras y logística, en seguimiento de proveedores, contratos y abastecimiento."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. Al completar el primer año obtenés el certificado de Asistente en Gestión de Proyectos Mineros, y al egresar, el título de Técnico Superior en Gestión de Proyectos Mineros."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. La Práctica Profesionalizante se cursa en el bimestre 8: son 340 horas reloj, 40 virtuales y 300 en una organización. Para hacerla se necesitan al menos 8 materias aprobadas, según las correlatividades del plan."},{"pregunta":"¿Cuánto dura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres, y se cursa 100% online."},{"pregunta":"¿Incluye normativa minera?","respuesta":"Sí. En el primer cuatrimestre cursás Legislación de la industria minera."},{"pregunta":"¿Voy a aprender logística y abastecimiento?","respuesta":"Sí. La carrera incluye Bases operativas de logística y Gestión de servicios y proveedores, aplicadas a compras y abastecimiento en el entorno minero."},{"pregunta":"¿Se estudian herramientas digitales?","respuesta":"Sí. Cursás Tecnologías digitales aplicadas a la gestión minera y Gestión de información y análisis de datos operativos."}]}]' WHERE id = 244 AND titulo = 'Técnico Superior en Gestión de Proyectos Mineros' AND slides = '[{"type": "faq", "items": [
    {"pregunta": "¿Qué se aprende en la Tecnicatura en Gestión de Proyectos Mineros?",
     "respuesta": "Estudiás la industria minera, sus operaciones y su legislación, junto con gestión de proyectos, presupuestos, logística, proveedores y análisis de datos operativos. La formación suma tecnologías digitales aplicadas a la gestión minera."},
    {"pregunta": "¿Qué hace un técnico en Gestión de Proyectos Mineros?",
     "respuesta": "Organiza cronogramas, hitos y reportes de avance, procesa datos técnicos, operativos y administrativos, asiste en compras, contratos y seguimiento de proveedores, y utiliza indicadores y herramientas digitales de gestión."},
    {"pregunta": "¿Cuál es la salida laboral de Gestión de Proyectos Mineros?",
     "respuesta": "Empresas operadoras, en seguimiento de proyectos y control de gestión; proveedores y contratistas, en organización de servicios y documentación administrativa; consultoras especializadas, y áreas de compras y logística, en seguimiento de proveedores, contratos y abastecimiento."},
    {"pregunta": "¿Tiene certificado intermedio?",
     "respuesta": "Sí. Al completar el primer año obtenés el certificado de Asistente en Gestión de Proyectos Mineros, y al egresar, el título de Técnico Superior en Gestión de Proyectos Mineros."},
    {"pregunta": "¿Tiene prácticas?",
     "respuesta": "Sí. La Práctica Profesionalizante se cursa en el bimestre 8: son 340 horas reloj, 40 virtuales y 300 en una organización. Para hacerla se necesitan al menos 8 materias aprobadas, según las correlatividades del plan."}
  ]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué hace un Técnico Superior en Diseño de Producto Digital?","respuesta":"Colabora en la investigación de necesidades, la definición de requerimientos, la planificación de funcionalidades, la validación con usuarios y el análisis de desempeño del producto."},{"pregunta":"¿La carrera incluye diseño UX UI?","respuesta":"Sí. Trabaja fundamentos de experiencia de usuario, diseño centrado en el usuario, usabilidad y prototipado."},{"pregunta":"¿Voy a aprender sobre product management?","respuesta":"Sí: gestión operativa y estratégica de productos, historias de usuario, métricas, prioridades y roadmaps. Son roles del sector, no títulos adicionales."},{"pregunta":"¿Incluye práctica profesional?","respuesta":"Sí. El cuarto cuatrimestre incluye una Práctica Profesionalizante de 340 horas."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Diseño de Producto Digital, con acreditación nacional."},{"pregunta":"¿Cuánto dura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres, y se cursa 100% online."},{"pregunta":"¿La inteligencia artificial forma parte de la carrera?","respuesta":"Sí. Cursás Descubrimiento de productos digitales con IA e IA aplicada al diseño y gestión de producto, con usos en investigación, prototipado, análisis y organización del trabajo."},{"pregunta":"¿Qué relación tiene con el análisis de datos?","respuesta":"La carrera incluye análisis de producto, métricas e Inteligencia de negocios, para interpretar resultados y fundamentar decisiones sobre productos digitales."},{"pregunta":"¿Puedo obtener un certificado antes de recibirme?","respuesta":"Sí. Al completar el primer año obtenés el certificado intermedio de Asistente en Diseño de Producto Digital."}]}]' WHERE id = 249 AND titulo = 'Técnico Superior en Diseño de Producto Digital' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué hace un Técnico Superior en Diseño de Producto Digital?","respuesta":"Colabora en la investigación de necesidades, la definición de requerimientos, la planificación de funcionalidades, la validación con usuarios y el análisis de desempeño del producto."},{"pregunta":"¿La carrera incluye diseño UX UI?","respuesta":"Sí. Trabaja fundamentos de experiencia de usuario, diseño centrado en el usuario, usabilidad y prototipado."},{"pregunta":"¿Voy a aprender sobre product management?","respuesta":"Sí: gestión operativa y estratégica de productos, historias de usuario, métricas, prioridades y roadmaps. Son roles del sector, no títulos adicionales."},{"pregunta":"¿Incluye práctica profesional?","respuesta":"Sí. El cuarto cuatrimestre incluye una Práctica Profesionalizante de 340 horas."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Diseño de Producto Digital, con acreditación nacional."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Cuánto dura la carrera?","respuesta":"Dura 2 años y se cursa 100% online."},{"pregunta":"¿Necesito saber programar?","respuesta":"No se requieren conocimientos avanzados de programación. La formación incluye herramientas sin código y automatización."},{"pregunta":"¿Qué certificado intermedio ofrece?","respuesta":"Asistente en Inteligencia Artificial Estratégica, al completar el primer año."},{"pregunta":"¿Incluye práctica profesional?","respuesta":"Sí. El plan incluye una Práctica Profesionalizante en el último bimestre."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Gestión de Inteligencia Artificial y Transformación Digital."},{"pregunta":"¿Cómo se cursa?","respuesta":"Con clases en vivo que quedan grabadas, laboratorios virtuales y actividades prácticas desde el comienzo."},{"pregunta":"¿Qué hace un técnico en IA y Transformación Digital?","respuesta":"Detecta oportunidades para incorporar IA, automatiza procesos, implementa herramientas generativas, analiza datos, desarrolla asistentes inteligentes y gestiona proyectos de transformación digital en organizaciones."},{"pregunta":"¿Incluye inteligencia artificial generativa?","respuesta":"Sí. El plan trabaja modelos generativos, asistentes inteligentes, copilots y LLMs, y su aplicación a distintos procesos; en el segundo año cursás Diseño de asistentes inteligentes."},{"pregunta":"¿Tiene salida laboral?","respuesta":"Sí. Podés trabajar en áreas de tecnología, innovación, operaciones, marketing, experiencia del cliente y estrategia, en consultoras y agencias, o en proyectos propios."}]}]' WHERE id = 250 AND titulo = 'Técnico Superior en Gestión de Inteligencia Artificial y Transformación Digital' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Cuánto dura la carrera?","respuesta":"Dura 2 años y se cursa 100% online."},{"pregunta":"¿Necesito saber programar?","respuesta":"No se requieren conocimientos avanzados de programación. La formación incluye herramientas sin código y automatización."},{"pregunta":"¿Qué certificado intermedio ofrece?","respuesta":"Asistente en Inteligencia Artificial Estratégica, al completar el primer año."},{"pregunta":"¿Incluye práctica profesional?","respuesta":"Sí. El plan incluye una Práctica Profesionalizante en el último bimestre."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Gestión de Inteligencia Artificial y Transformación Digital."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Cuánto dura la carrera?","respuesta":"Dura 2 años y se cursa 100% online."},{"pregunta":"¿Qué se estudia?","respuesta":"Medios de pago, transacciones digitales, control de riesgos y fraude, regulación, blockchain y análisis de producto."},{"pregunta":"¿Qué certificado intermedio ofrece?","respuesta":"Asistente en Administración de Negocios Digitales Financieros, al completar el primer año."},{"pregunta":"¿Incluye práctica profesional?","respuesta":"Sí. El plan incluye una Práctica Profesionalizante en el último cuatrimestre."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Administración de Negocios Digitales Financieros."},{"pregunta":"¿Cómo se cursa?","respuesta":"100% online, con clases en vivo que quedan grabadas, laboratorios virtuales y actividades prácticas."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con Ecosistema financiero digital y Operaciones financieras en el primer cuatrimestre."},{"pregunta":"¿Me prepara para trabajar en un banco o una fintech?","respuesta":"Sí. Prepara para tareas de operaciones, análisis de negocio, prevención de fraude, experiencia del cliente y soporte de producto, en bancos, fintech, billeteras virtuales, neobancos y procesadoras de pagos, según los requisitos de cada puesto."},{"pregunta":"¿Qué diferencia hay con una licenciatura en finanzas?","respuesta":"Esta tecnicatura dura 2 años y se concentra en la gestión operativa de servicios financieros digitales. Para comparar con una licenciatura, conviene revisar el título, el plan y el alcance profesional de cada una."}]}]' WHERE id = 252 AND titulo = 'Técnico Superior en Administración de Negocios Digitales Financieros' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Cuánto dura la carrera?","respuesta":"Dura 2 años y se cursa 100% online."},{"pregunta":"¿Qué se estudia?","respuesta":"Medios de pago, transacciones digitales, control de riesgos y fraude, regulación, blockchain y análisis de producto."},{"pregunta":"¿Qué certificado intermedio ofrece?","respuesta":"Asistente en Administración de Negocios Digitales Financieros, al completar el primer año."},{"pregunta":"¿Incluye práctica profesional?","respuesta":"Sí. El plan incluye una Práctica Profesionalizante en el último cuatrimestre."},{"pregunta":"¿Qué título se obtiene?","respuesta":"Técnico Superior en Administración de Negocios Digitales Financieros."}]}]';
